// === Tab: mySketch ===
var scale;
var mPwr;
var decay;
var cents;


var particlesQuantity = 100;

var positionX = new Array(particlesQuantity);
var positionY = new Array(particlesQuantity);
var velocityX = new Array(particlesQuantity).fill(0);
var velocityY = new Array(particlesQuantity).fill(0);
var mass = new Array(particlesQuantity);

function setup() {
	createCanvas(windowWidth, windowHeight);
	var m = [width/2, height/2]
	cents = [new center(m[0],m[1],width, height), new center(m[0],m[1],width, height), new center(m[0],m[1],width, height)];
	noStroke();
	fill(255, 255, 255, 6);
	scale = createSlider(0, 600, 300, 10);
  scale.position(10, 10);
  scale.style('width', '80px');
	decay = createSlider(0, 600, 100, 10);
  decay.position(10, 30);
  decay.style('width', '80px');
	mPwr = createSlider(0, 600, 400, 10);
  mPwr.position(10, 50);
  mPwr.style('width', '80px');

	for (var particle = 0; particle < particlesQuantity; particle++) {
		positionX[particle] = width/2;
		positionY[particle] = height/2;
		mass[particle] = random(.1, 2);
	}
	maxi = (sqrt(pow(width, 2)) + pow(height, 2));
}

function draw() {
	//background(255, 255, 255, 1);
	fill(255*noise(frameCount/500+230), 255*noise(frameCount/600+734), 255*noise(frameCount/433));
	stroke(255*noise(frameCount/500+180), 255*noise(frameCount/600+784), 255*noise(frameCount/383), 3);
	for (var particle = 0; particle < particlesQuantity; particle++) {
		velocityX[particle] = 0
		velocityY[particle] = 0
		for (var p2 = 0; p2 < particlesQuantity; p2++) {
			v = createVector(positionX[particle]-positionX[p2], positionY[particle]-positionY[p2]);
			if (v.mag()<scale.value()+decay.value()){
				newMag = (v.mag()-scale.value())*.0003*mass[p2];
			} else {
				newMag = (constrain((decay.value()*2+scale.value())-v.mag(), 0, 200))*.0003*mass[p2];
			}
			v.rotate(random(-.1, .1))
			v.setMag(newMag)
			velocityX[particle] -= v.x;
			velocityY[particle] -= v.y;
		}

		for (i=0; i<cents.length; i++){
			var c = cents[i];
			v = createVector(positionX[particle]-c.pos.x, positionY[particle]-c.pos.y);
			newMag = (constrain(mPwr.value()-v.mag(), 0, 200))*.03;
			v.setMag(newMag)
			velocityX[particle] -= v.x;
			velocityY[particle] -= v.y;
		}

		positionX[particle] += velocityX[particle];
		positionY[particle] += velocityY[particle];


		if ((positionX[particle] < 0 && velocityX[particle] < 0) || (positionX[particle] > width && velocityX[particle] > 0)) {

			velocityX[particle] = -velocityX[particle];
		}

		if ((positionY[particle] < 0 && velocityY[particle] < 0) || (positionY[particle] > height && velocityY[particle] > 0)) {

			velocityY[particle] = -velocityY[particle];
		}

		rect(positionX[particle], positionY[particle], velocityX[particle]*10, velocityY[particle]*10);
	}

	for (i=0; i<cents.length; i++){
			cents[i].move();
		}
}

class center{

	constructor(x, y, w, h){
		this.pos = createVector(x, y);
		this.speed = 6;
		this.life = random(80000, 1000000);
		this.w = w;
		this.h = h;
		this.n = createVector(random(-10,10), random(-10, 10))
		this.n.setMag(this.speed)
	}

	move(){

		this.pos.add(this.n)
		if(this.pos.x>this.w||this.pos.x<0||this.pos.y>height||this.pos.y<0){
			//this.pos = createVector(constrain(this.pos.x, 0, this.w), constrain(this.pos.y, 0, this.y))
			this.n.rotate(PI)
		}else{
			this.n.rotate(.1*(noise(frameCount/100 + this.life)-.5))	
		}
	}
}

